    public function testListHistory(): void
    {
        $this->queueJson(200, '{"count":1,"next":null,"previous":null,"results":[{"version":1,"snapshot":"snapshot-value","actor_email":"user@example.com","published_at":"2026-01-15T10:30:00Z"}]}');

        $result = $this->client->cases->blueprints->listHistory('blueprintUuid-1', [
            'ordering' => 'ordering-value',
            'limit' => 1,
            'offset' => 1,
        ]);

        $request = $this->lastRequest();
        self::assertSame('GET', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/organization/org-7f3a/application/app-91c2/cases/blueprints/blueprintUuid-1/history/', $request->getUri()->getPath());
        self::assertSame([
            'ordering' => 'ordering-value',
            'limit' => '1',
            'offset' => '1',
        ], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('', (string) $request->getBody());
        self::assertCount(1, $result->results);
        self::assertContainsOnlyInstancesOf(Types\CasePublicationPolicyRevision::class, $result->results);
        self::assertFalse($result->hasNextPage());
        self::assertSame($this->decoded('{"count":1,"next":null,"previous":null,"results":[{"version":1,"snapshot":"snapshot-value","actor_email":"user@example.com","published_at":"2026-01-15T10:30:00Z"}]}'), $result->toArray());
    }
